function loomara_room_collections(){
    $groups=['bedroom'=>['Bedroom','Slow mornings. Softer evenings.','Layer your bed with sheets, comforters and coordinated sets.',['bedsheets','comforters','combo']],'living'=>['Living spaces','Small details. A different feeling.','Bring colour and pattern to your favourite corner with cushion covers.',['cushion-covers']]];
    ob_start();echo '<div class="loomara-room-editorial"><section class="room-intro"><div><p class="eyebrow">Make room for comfort</p><h2>A softer space,<br>your way.</h2><p>Start with the room you love. Find the layers that make it feel like home.</p><nav aria-label="Choose a room"><a class="room-primary" href="#room-bedroom">Explore the bedroom <span aria-hidden="true">↗</span></a><a class="room-secondary" href="#room-living">Explore living spaces <span aria-hidden="true">↗</span></a></nav></div><img src="'.esc_url(get_template_directory_uri().'/assets/home-rest-considered.jpg').'" width="1317" height="1194" alt="A sunlit bedroom layered with floral bedding and navy cushions." decoding="async" fetchpriority="high"></section>';
    foreach($groups as $id=>[$name,$headline,$description,$slugs]){echo '<section class="room-collection" id="room-'.esc_attr($id).'" aria-labelledby="room-title-'.esc_attr($id).'"><header><div><p class="eyebrow">'.esc_html($name).'</p><h2 id="room-title-'.esc_attr($id).'">'.esc_html($headline).'</h2></div><p>'.esc_html($description).'</p></header><div class="room-category-grid">';foreach($slugs as $slug){$term=get_term_by('slug',$slug,'product_cat');if(!$term){continue;}$url=get_term_link($term);if(is_wp_error($url)){continue;}echo '<article><a class="room-art-link" href="'.esc_url($url).'" aria-label="Shop '.esc_attr($term->name).'"><img src="'.esc_url(get_template_directory_uri().'/assets/home-category-'.$slug.'.jpg').'" width="832" height="467" alt="'.esc_attr($term->name).' collection" loading="lazy" decoding="async"></a><div class="room-category-caption"><a href="'.esc_url($url).'">Explore '.esc_html($term->name).' <span aria-hidden="true">↗</span></a><div class="room-style-links" aria-label="'.esc_attr($term->name).' styles">';foreach(loomara_room_children($term->term_id) as $child){$link=get_term_link($child);if(!is_wp_error($link)){echo '<a href="'.esc_url($link).'">'.esc_html($child->name).'</a>';}}echo '</div></div></article>';}echo '</div></section>';}
    echo '<div class="room-closing"><p>Not sure where to begin?</p><a class="room-primary" href="'.esc_url(home_url('/shop/')).'">Explore every layer <span aria-hidden="true">↗</span></a><a class="room-secondary" href="'.esc_url(home_url('/contact/')).'">Ask Loomara</a></div></div>';return ob_get_clean();
}
