function loomara_room_home_feature(){
    $page=get_page_by_path('shop-by-room',OBJECT,'page');if(!$page||$page->post_status!=='publish'||!str_contains($page->post_content,'[loomara_room_collections]')){return;}
    echo '<section class="home-room-feature" aria-labelledby="home-room-title"><div class="home-room-copy"><p class="eyebrow">Shop by room & style</p><h2 id="home-room-title">Comfort, in every corner.</h2><p>Soft layers for the bedroom. Thoughtful accents for the spaces between. Find a little more home in every room.</p><a class="room-primary" href="'.esc_url(get_permalink($page)).'">Shop by room & style <span aria-hidden="true">↗</span></a></div><a class="home-room-art" href="'.esc_url(get_permalink($page)).'" aria-label="Explore rooms and styles"><img src="'.esc_url(get_template_directory_uri().'/assets/home-rest-considered.jpg').'" width="1317" height="1194" alt="A softly layered bedroom with floral bedding and navy cushions." loading="lazy" decoding="async"></a></section>';
}
function loomara_store_pages_settings(){
    if(!current_user_can('manage_options')){return;}
    echo '<section><h2>Customer discovery pages</h2><p>Create only the missing room/style page. Existing pages are never overwritten. Published matching pages are linked from Shop.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="loomara_store_pages">';wp_nonce_field('loomara_store_pages');echo '<button class="button">Create missing discovery pages</button></form></section>';
}
add_action('admin_post_loomara_store_pages',function(){
    if(($_SERVER['REQUEST_METHOD']??'')!=='POST'||!current_user_can('manage_options')){wp_die('Administrator access required.','',['response'=>403]);}check_admin_referer('loomara_store_pages');
    foreach(loomara_store_page_plan() as $slug=>$plan){$existing=get_page_by_path($slug,OBJECT,'page');if($existing){if($existing->post_status!=='publish'||!str_contains($existing->post_content,$plan[1])){wp_die('An existing destination needs review; it has not been changed.','',['response'=>409]);}continue;}$id=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_name'=>$slug,'post_title'=>$plan[0],'post_content'=>$plan[1]],true);if(is_wp_error($id)||!$id){wp_die('Page creation failed. Existing pages were not changed.','',['response'=>500]);}}
    wp_safe_redirect(admin_url('admin.php?page=loomara-settings'));exit;
});
add_action('woocommerce_before_shop_loop',function(){
    if(is_search()){return;}$links=[];foreach(loomara_store_page_plan() as $slug=>$plan){$p=get_page_by_path($slug,OBJECT,'page');if($p&&$p->post_status==='publish'&&str_contains($p->post_content,$plan[1])){$links[]='<a href="'.esc_url(get_permalink($p)).'">'.esc_html($plan[0]).' →</a>';}}if($links){echo '<nav class="loomara-discovery-links" aria-label="Explore your home">'.implode(' ',$links).'</nav>';}
},5);
add_action('init',function(){register_post_type('loomara_case',['label'=>'Customer support cases','public'=>false,'show_ui'=>true,'show_in_menu'=>'woocommerce','show_in_rest'=>false,'supports'=>['title'],'capabilities'=>['edit_posts'=>'manage_woocommerce','edit_others_posts'=>'manage_woocommerce','publish_posts'=>'manage_woocommerce','read_private_posts'=>'manage_woocommerce','delete_posts'=>'manage_options','create_posts'=>'do_not_allow'],'map_meta_cap'=>true]);});
add_filter('wp_insert_post_data',function($data,$input){if(($data['post_type']??'')==='loomara_case'&&!in_array($data['post_status']??'',['trash','auto-draft'],true)){$data['post_status']='private';if(!empty($input['ID'])){$old=get_post((int)$input['ID']);if($old&&$old->post_type==='loomara_case'){$data['post_author']=$old->post_author;}}}return $data;},10,2);
function loomara_cases_panel(){
    if(!is_user_logged_in()||!function_exists('wc_get_orders')){return;}
    echo '<section class="loomara-tools"><h2>Customer support cases</h2><p>For order questions only. Submitting a case does not cancel an order, start a return or request a refund. Please use the dedicated order actions for those requests. Check this page for replies.</p>';
    $cases=get_posts(['post_type'=>'loomara_case','post_status'=>'private','author'=>get_current_user_id(),'numberposts'=>20,'orderby'=>'ID','order'=>'DESC']);
    foreach($cases as $case){$reply=get_post_meta($case->ID,'_loomara_case_reply',true);$status=get_post_meta($case->ID,'_loomara_case_status',true)==='resolved'?'Resolved':'Open';$linked=wc_get_order(get_post_meta($case->ID,'_loomara_case_order',true));echo '<details><summary>Case #'.absint($case->ID).' — '.esc_html($case->post_title).' · '.esc_html($status).'</summary>';if(loomara_journey_owner($linked)){echo '<p><strong>Order:</strong> <a href="'.esc_url($linked->get_view_order_url()).'">'.esc_html($linked->get_order_number()).'</a><br><strong>Products:</strong> '.esc_html(loomara_case_product_titles($linked)).'</p>';}echo '<p>'.nl2br(esc_html($case->post_content)).'</p><p><strong>Loomara reply:</strong> '.($reply?nl2br(esc_html($reply)):'Awaiting a team response.').'</p></details>';}
    $orders=wc_get_orders(['customer_id'=>get_current_user_id(),'limit'=>30,'orderby'=>'date','order'=>'DESC']);$token=wp_generate_uuid4();
    echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="loomara_create_case"><input type="hidden" name="token" value="'.esc_attr($token).'">';wp_nonce_field('loomara_case_'.$token,'case_nonce');
    echo '<label>Order<select name="order_id" required><option value="">Choose your order</option>';foreach($orders as $o){echo '<option value="'.absint($o->get_id()).'">'.esc_html($o->get_order_number().' - '.loomara_case_product_titles($o,3)).'</option>';}echo '</select></label><label>Subject<input name="subject" maxlength="120" required></label><label>How can we help?<textarea name="message" maxlength="3000" required></textarea></label><p>Do not include card details, passwords or bank credentials. Recent 20 cases and 30 orders are shown. Contact us for older orders.</p><button class="button">Create support case</button></form></section>';
}
add_action('woocommerce_account_dashboard','loomara_cases_panel',30);
add_action('admin_post_loomara_create_case',function(){
    $token=sanitize_text_field(wp_unslash($_POST['token']??''));$o=function_exists('wc_get_order')?wc_get_order(absint($_POST['order_id']??0)):false;
    if($_SERVER['REQUEST_METHOD']!=='POST'||!preg_match('/^[a-f0-9-]{36}$/i',$token)||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['case_nonce']??'')),'loomara_case_'.$token)||!loomara_journey_owner($o)){wp_die('Not allowed.','',['response'=>403]);}
    $subject=sanitize_text_field(wp_unslash($_POST['subject']??''));$message=sanitize_textarea_field(wp_unslash($_POST['message']??''));
    if(!$subject||!$message||strlen($subject)>120||strlen($message)>3000){wp_die('Please enter a short subject and message.');}
    $recent=get_posts(['post_type'=>'loomara_case','post_status'=>'private','author'=>get_current_user_id(),'date_query'=>[['after'=>'1 hour ago']],'numberposts'=>5,'fields'=>'ids']);
    if(count($recent)>=5||!loomara_buy_again_claim(-1,$token)){wp_die('Please review existing cases or try again later.');}
    $id=wp_insert_post(['post_type'=>'loomara_case','post_status'=>'private','post_author'=>get_current_user_id(),'post_title'=>$subject,'post_content'=>$message],true);
    if(is_wp_error($id)){wp_die('Unable to save the case. Please contact us.');}update_post_meta($id,'_loomara_case_order',$o->get_id());wp_safe_redirect(wc_get_page_permalink('myaccount'));exit;
});
function loomara_case_product_titles($order,$limit=20){
    if(!$order instanceof WC_Order){return 'Order unavailable';}$items=$order->get_items();$names=[];
    foreach(array_slice($items,0,max(1,min(20,(int)$limit))) as $item){$name=trim(wp_strip_all_tags($item->get_name()));if($name!==''){$names[]=$name;}}
    $extra=count($items)-max(1,min(20,(int)$limit));if($extra>0){$names[]='+'.$extra.' more';}return $names?implode(', ',$names):'Product details unavailable';
}
add_filter('manage_loomara_case_posts_columns',function($columns){$columns['loomara_case_order']='Order';$columns['loomara_case_products']='Products';return $columns;});
add_action('manage_loomara_case_posts_custom_column',function($column,$id){if(!current_user_can('manage_woocommerce')||!in_array($column,['loomara_case_order','loomara_case_products'],true)){return;}$order=wc_get_order(get_post_meta($id,'_loomara_case_order',true));if(!$order){echo 'Order unavailable';return;}if($column==='loomara_case_order'){echo '<a href="'.esc_url($order->get_edit_order_url()).'">'.esc_html($order->get_order_number()).'</a>';}else{echo esc_html(loomara_case_product_titles($order));}},10,2);
add_action('add_meta_boxes_loomara_case',function(){add_meta_box('loomara-case-review','Order and customer reply',function($post){if(!current_user_can('manage_woocommerce')){return;}$order=wc_get_order(get_post_meta($post->ID,'_loomara_case_order',true));wp_nonce_field('loomara_review_case','case_review_nonce');echo '<p>Order: '.($order?'<a href="'.esc_url($order->get_edit_order_url()).'">'.esc_html($order->get_order_number()).'</a>':'Unavailable').'</p><p><strong>Products:</strong> '.esc_html(loomara_case_product_titles($order)).'</p><h3>Customer message</h3><p>'.nl2br(esc_html($post->post_content)).'</p><label>Customer-visible reply<textarea style="width:100%" rows="6" name="case_reply" maxlength="3000">'.esc_textarea(get_post_meta($post->ID,'_loomara_case_reply',true)).'</textarea></label><label><input type="checkbox" name="case_resolved" value="1" '.checked(get_post_meta($post->ID,'_loomara_case_status',true),'resolved',false).'> Resolved</label><p>Saving publishes this reply in the customer’s account. No email is sent.</p>';});});
add_action('save_post_loomara_case',function($id){if(wp_is_post_revision($id)||!current_user_can('manage_woocommerce')||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['case_review_nonce']??'')),'loomara_review_case')){return;}update_post_meta($id,'_loomara_case_reply',substr(sanitize_textarea_field(wp_unslash($_POST['case_reply']??'')),0,3000));update_post_meta($id,'_loomara_case_status',isset($_POST['case_resolved'])?'resolved':'open');});
add_action('admin_menu',function(){add_submenu_page('woocommerce','Integration health','Integration health','manage_options','loomara-integration-health','loomara_integration_health');});
function loomara_health_stage($stage){return in_array($stage,['review','failed','uncertain','error'],true)?'Needs attention':(in_array($stage,['waiting','shipping_wait','requested','pending'],true)?'Waiting':'Recorded state');}
function loomara_health_details($job,$scheduled=0,$now=null){
    $now=$now??time();$stage=is_string($job['stage']??null)?sanitize_key($job['stage']):'unknown';
    $active=in_array($stage,['queued','waiting','shipping_wait','requested','pending','refund_pending','refund_submitting','refund_uncertain'],true);
    $details=['stage'=>$stage,'active'=>$active,'attempts'=>isset($job['attempts'])&&is_numeric($job['attempts'])?max(0,(int)$job['attempts']):null];
    foreach(['created','updated','next_check','deadline','retry_until'] as $field){$value=$job[$field]??0;$details[$field]=is_numeric($value)&&$value>0?(int)$value:0;}
    $details['scheduled']=is_numeric($scheduled)&&$scheduled>0?(int)$scheduled:0;
    $details['overdue']=$active&&max($details['next_check'],$details['scheduled'])>0&&max($details['next_check'],$details['scheduled'])<$now-900;
    $explanations=['queued'=>'Queued for guarded verification.','requested'=>'Cancellation requested; shipping verification is pending.','shipping_wait'=>'Waiting for exact shipping/cancellation confirmation.','waiting'=>'Waiting for the shipping-detail check.','refund_submitting'=>'Refund submission intent saved; verify provider state before any resubmission.','refund_uncertain'=>'Refund outcome is uncertain. Reconcile with Razorpay; do not submit another refund.','refund_pending'=>'Refund is pending at the provider; bank completion is not confirmed.','review'=>'Team review required. Inspect the protected workflow tool and order notes before taking action.','failed'=>'A failure was recorded; inspect the workflow tool.','uncertain'=>'Outcome uncertain; verify provider state before retrying.','error'=>'An error was recorded; inspect the workflow tool.','complete'=>'Workflow recorded complete. This does not guarantee bank posting.','confirmed'=>'Cancellation confirmation was recorded; refund is a separate workflow.','finished'=>'Detail/email workflow finished; this is not proof of shipment delivery or inbox receipt.','skipped'=>'Workflow was skipped; inspect the order for context.'];
    $details['explanation']=$explanations[$stage]??'Saved stage; inspect the linked order and integration tool for context.';
    return $details;
}
function loomara_health_time($at){return $at?wp_date('d M Y · g:i a',(int)$at,new DateTimeZone('Asia/Kolkata')).' IST':'Not recorded';}
function loomara_integration_health(){
    if(!current_user_can('manage_options')){return;}
    echo '<div class="wrap"><h1>Integration health — read only</h1><p>This is a bounded local-record snapshot, not a live API test. Opening it does not contact Shiprocket/Razorpay, send emails or run jobs. Saved verification does not prove current connectivity.</p>';
    $at=(int)get_option('loomara_shiprocket_verified_at',0);echo '<p>Shiprocket last saved verification: <strong>'.esc_html($at?wp_date('d M Y H:i T',$at):'Not recorded').'</strong></p><p>WordPress automatic cron: '.(defined('DISABLE_WP_CRON')&&DISABLE_WP_CRON?'Disabled in configuration; verify an external scheduler.':'Enabled in configuration; execution still depends on site traffic or an external scheduler.').'</p>';
    if(!function_exists('wc_get_orders')){echo '<p>WooCommerce unavailable.</p></div>';return;}
    echo '<h2>Recent workflow records</h2><p>Latest 100 orders only; missing records mean “not recorded”, not success. Review older orders in the dedicated integration tools.</p><table class="widefat striped"><thead><tr><th>Order</th><th>Workflow</th><th>Saved stage</th><th>Observation</th></tr></thead><tbody>';
    $count=0;foreach(wc_get_orders(['limit'=>100,'orderby'=>'date','order'=>'DESC']) as $o){foreach(['loomara_cancel_request_124_'=>['Cancellation','loomara_cancel_request_124'],'loomara_refund_110_'=>['Refund','loomara_auto_refund_110'],'loomara_tracking_job_112_'=>['Shipment details','loomara_tracking_email_112'],'loomara_pickup_tracking_job_'=>['Readiness details','loomara_pickup_tracking_email']] as $prefix=>[$label,$hook]){$job=get_option($prefix.$o->get_id(),[]);if(!is_array($job)||empty($job['stage'])){continue;}$scheduled=wp_next_scheduled($hook,[$o->get_id()]);if($hook==='loomara_cancel_request_124'&&function_exists('as_next_scheduled_action')){$as=as_next_scheduled_action($hook,[$o->get_id()],'loomara-cancellation');if(is_numeric($as)&&$as>0){$scheduled=$scheduled?min($scheduled,$as):$as;}}$d=loomara_health_details($job,$scheduled);$observation=loomara_health_stage($d['stage']);if($d['stage']==='refund_uncertain'){$observation='Needs attention';}elseif(in_array($d['stage'],['refund_pending','refund_submitting','queued'],true)){$observation='Waiting';}echo '<tr><td><a href="'.esc_url($o->get_edit_order_url()).'">'.esc_html($o->get_order_number()).'</a></td><td>'.esc_html($label).'</td><td>'.esc_html($d['stage']).'</td><td>'.esc_html($observation).'<details style="margin-top:8px"><summary>Workflow details</summary><p>'.esc_html($d['explanation']).'</p><p><strong>Order status:</strong> '.esc_html(wc_get_order_status_name($o->get_status())).'<br><strong>Products:</strong> '.esc_html(loomara_case_product_titles($o)).'<br><strong>Recorded attempts:</strong> '.esc_html($d['attempts']===null?'Not recorded':(string)$d['attempts']).'</p><dl>';foreach(['created'=>'Created','updated'=>'Last saved update','next_check'=>'Saved next-check time','scheduled'=>'Next scheduled event','deadline'=>'Initial waiting-window limit','retry_until'=>'Extended retry-window limit'] as $field=>$title){echo '<dt><strong>'.esc_html($title).'</strong></dt><dd>'.esc_html(loomara_health_time($d[$field])).'</dd>';}echo '</dl>';if($d['overdue']){echo '<p><strong>Check overdue by more than 15 minutes.</strong> Inspect scheduling and order notes; this screen will not run it.</p>';}if($d['active']&&!$d['scheduled']){echo '<p>No pending event found in the checked schedulers. The worker may be running, or its schedule needs review. This is not proof that it is stuck.</p>';}echo '<p>Provider payloads, free-text errors and credentials are deliberately excluded. Use the dedicated workflow tool for a protected investigation.</p></details></td></tr>';$count++;}}
    if(!$count){echo '<tr><td colspan="4">No workflow records found in this sample.</td></tr>';}echo '</tbody></table><p>No credentials or customer contact details are displayed.</p></div>';
}
add_action('wp_enqueue_scripts',function(){if(is_front_page()||is_page()||(function_exists('is_shop')&&(is_shop()||is_product_taxonomy()))||(function_exists('is_account_page')&&is_account_page())){wp_enqueue_style('loomara-store-tools',get_template_directory_uri().'/assets/store-tools.css',[],filemtime(get_template_directory().'/assets/store-tools.css'));}});
